class TaskList {
  #tasks = [];
  add(title) {
    const task = { id: this.#tasks.length + 1, title, done: false };
    this.#tasks.push(task);
  }
  complete(id) {
    this.#tasks.find((t) => t.id === id).done = true;
  }
  get openCount() {
    return this.#tasks.filter((task) => !task.done).length;
  }
}

const list = new TaskList();
list.add("Buy milk");
list.add("Call Ada");
list.add("Fix sink");
list.complete(2);
console.log(list.openCount);

class TaskList {
  #tasks = [];
