  constructor({ listeners = [] } = {}) {
    this.#listeners = listeners;
  }
  add(title) {
    const task = { id: this.#tasks.length + 1, title };
    this.#tasks.push(task);
    for (const listener of this.#listeners) listener("added", task);
  }
}

const trail = [];
const audit = (event, task) => trail.push(`${event} #${task.id}`);

new TaskList().add("Nobody hears this");
const watched = new TaskList({ listeners: [audit] });
watched.add("Buy milk");
watched.add("Call Ada");
console.log(trail);

