class Task {
  constructor(title) {
    this.title = title;
    this.done = false;
  }

  static fromJSON(text) {
    const data = JSON.parse(text);
    const task = new Task(data.title);
    task.done = data.done === true;
    return task;
  }
}

const a = Task.fromJSON('{"title":"Write report","done":true}');
const b = Task.fromJSON('{"title":"Call Ada","done":"yes"}');
console.log(a.title, a.done, b.done);

